package com.shanjay.mart.service;
import com.shanjay.mart.dao.UserDAO; import com.shanjay.mart.model.User; import com.shanjay.mart.util.Password;
public class AuthService {private final UserDAO dao;public AuthService(UserDAO d){dao=d;} public User login(String e,String p)throws Exception{User u=dao.findByEmail(e);return u!=null&&Password.matches(p,u.passwordHash)?u:null;} public void register(String n,String e,String p,String role)throws Exception{if(n==null||n.isBlank()||e==null||e.isBlank()||p==null||p.length()<4)throw new IllegalArgumentException("Please enter valid details.");if(dao.emailExists(e))throw new IllegalArgumentException("Email already registered.");if(!role.equals("BUYER")&&!role.equals("SELLER"))throw new IllegalArgumentException("Invalid role.");dao.create(n,e,Password.hash(p),role);}}
